  class BScreen {
  		BRect		Frame();
+ 		float		DeviceScale();
+ 			// frame buffer pixels per coordinate unit, 1.5 at 150%

  enum bitmap_drawing_options {
  	B_FILTER_BITMAP_BILINEAR	= 0x00000100,
  	B_WAIT_FOR_RETRACE		= 0x00000800,
+ 	B_DEVICE_PIXEL_BITMAP		= 0x00001000
  };

+ typedef struct display_scan_timing {
+ 	uint32		output_id;	// 0: the outputs share one blank
+ 	uint32		flags;		// B_SCAN_TIMING_FROM_HARDWARE / _FROM_BLANK
+ 	BRect		frame;		// the output, in screen coordinates
+ 	clipping_rect	device_frame;	// and in frame buffer pixels
+ 	bigtime_t	scan_start;	// system_time() of a frame's start
+ 	bigtime_t	period;		// the next ones every period
+ 	uint32		generation;	// changes with the layout and modes
+ } display_scan_timing;

  		status_t	WaitForRetrace(bigtime_t timeout);
+ 		status_t	WaitForOutputRetrace(BRect frame,
+ 				bigtime_t timeout = B_INFINITE_TIMEOUT);
+ 		status_t	GetScanTiming(BRect frame,
+ 				display_scan_timing* timing);

  rgb_color	tint_color(rgb_color color, float tint);

+ // Light or dark appearance (air/OS). Each has its own palette of UI colors;
+ // switching makes the other palette current, and applications get
+ // B_COLORS_UPDATED as for any change of colors.
+ bool		ui_dark_mode();
+ void		set_ui_dark_mode(bool dark);

  enum {
  	B_DISABLE_ANTIALIASING	= 0x00000001,
  	B_FORCE_ANTIALIASING	= 0x00000002,
+ 	B_COLOR_GLYPHS_AS_SHAPES = 0x00000004
  };

